/**
 * Provenance of a projected recovery-action argument value.
 */
export type ActionArgumentSource =
  | "operator_action.verdict_context"
  | "operator_action.condition_evidence"
  | "operator_action.request_context";

/**
 * Whether a recovery-action argument has a concrete projected value.
 */
export type ActionArgumentStatus = "resolved" | "missing";

/**
 * Stable action identity; catalogue resolution is owned by a later layer.
 */
export type ActionReference = {
  action_id: string;
};

/**
 * One registry modelo the operator must investigate, with its reason.
 */
export type AdvisedObligation = {
  modelo: string;
  reason: CoverageAdviceReason;
};

/**
 * Whether a modelo applies to a taxpayer, derived from its model.
 *
 * Attributes: APPLICABLE: The declared taxpayer model triggers this modelo.
 * NOT_APPLICABLE: The declared taxpayer model positively excludes this modelo
 * (e.g. a landlord has no Modelo 130 obligation; a sociedad limitada files no
 * Modelo 100). ATTRIBUTION_PASS_THROUGH: The profile is an attribution entity
 * and the modelo is a cuota self-assessment (Modelo 100 / 130 / 200 / 202).
 * The entity runs no IS and no IRPF cuota of its own — the régimen de
 * atribución de rentas (LIRPF Title X Section 2) attributes the income to the
 * members, who file the substantive tax. The honest answer to "what is my
 * cuota" is "none — the income is taxed in the members' returns". Distinct
 * from `NOT_APPLICABLE`, which means the taxpayer files a *different* cuota.
 * INCOMPLETE: The taxpayer model is not declared in enough detail to decide,
 * or the entity form is recognised-but-unsupported. The engine refuses to
 * guess — the operator must declare their taxpayer type first.
 */
export type ApplicabilityVerdict =
  "applicable" | "not_applicable" | "attribution_pass_through" | "incomplete";

export type CalculationRevisionId = string;

/**
 * Breakdown of explicit profile values versus deadline-engine defaults.
 */
export type CalendarCompleteness = {
  explicitly_set_keys: string[];
  defaulted_keys: string[];
  computable_modelos: string[];
  defaulted_modelos: string[];
};

/**
 * Why an unsurfaced obligation is advised rather than silently dropped.
 *
 * Attributes: APPLICABLE_WINDOW_MISSING: The taxpayer model positively
 * triggers the modelo (verdict `APPLICABLE`) but the registry carries no
 * deadline window for it, so the engine never placed it on the calendar. This
 * is the former Modelo-190 shape — a genuine data gap.
 * APPLICABILITY_UNDETERMINED: The seed applicability table cannot yet decide
 * the modelo for this profile (verdict `INCOMPLETE` — no seed rule, or a
 * payer/enrolment fact left undeclared). The operator must investigate whether
 * it applies. REGISTRY_UNMODELED: The modelo is a recognized AEAT obligation
 * (`UNMODELED_OBLIGATIONS`) that the registry does not model at all, so
 * neither a window nor an applicability rule exists. It surfaces as advised —
 * "AEAT may expect this; the app cannot yet scope it" — rather than being
 * invisible.
 *
 * `UNMODELED_OBLIGATIONS` is intentionally empty today, so no production input
 * reaches this disposition: the out-of-scope partition resolves first. The
 * branch is kept deliberately, not pending deletion — it is the advisory
 * capability for taxpayers whose obligation is registry-less, and populating
 * the declaration is a per-entry tax review against official sources rather
 * than a coding change. See that declaration for the full reasoning.
 */
export type CoverageAdviceReason =
  | "applicable_window_missing"
  | "applicability_undetermined"
  | "registry_unmodeled";

/**
 * Closed identifier for one ordered data-prep walkthrough step.
 */
export type DataPrepStepId =
  | "import_transactions"
  | "classify_transactions"
  | "attach_evidence"
  | "register_invoices"
  | "resolve_readiness"
  | "start_modelo_work";

/**
 * Closed lifecycle state for one data-prep walkthrough step.
 *
 * Attributes: DONE: The step's readiness condition is fully satisfied for the
 * requested scope. IN_PROGRESS: Some but not all of the step's underlying
 * facts are present (e.g. some transactions classified, others not). PENDING:
 * The step has not been started for the requested scope. BLOCKED: The step
 * cannot proceed because an upstream capability the step depends on is not yet
 * available in this application.
 */
export type DataPrepStepState = "done" | "in_progress" | "pending" | "blocked";

/**
 * Which holiday layers were checked when a close date was adjusted.
 *
 * An electronic filing close moves only for weekends and the national
 * inhábiles (Ley 39/2015 art. 31.3, which excludes art. 30.6), so the national
 * calendar is the complete rule for every filer.
 *
 * * `NATIONAL_ONLY` — weekends and national inhábiles were checked; the
 * adjusted date is final. * `NOT_SHIFTED` — the modelo's deadline does not
 * move for non-working days, so no calendar applies. * `CALENDAR_UNAVAILABLE`
 * — the holiday calendar could not be resolved and the original close date was
 * kept unverified.
 */
export type DeadlineHolidayCoverage =
  "national_only" | "not_shifted" | "calendar_unavailable";

export type FilingRecordId = string;

/**
 * Layer of government that declared the holiday.
 *
 * * `NATIONAL` — declared by the State; observed everywhere. * `CCAA` —
 * declared by an autonomous community; observed only in that CCAA's territory.
 *
 * Only a national holiday moves a filing close (Ley 39/2015 art. 31.3); a
 * regional holiday counts only for a procedure that declares the territory
 * whose calendar it uses. The registry carries no municipal holiday source.
 */
export type HolidayJurisdiction = "national" | "ccaa";

