/**
 * Severity of a single operator-facing `Notice`.
 *
 * `info` is a non-fatal next-step hint or informational advisory; `warning` is
 * a non-blocking advisory the operator should act on. A command that attaches
 * any `warning` notice resolves to `WARNING` through `derive_status`.
 */
export type NoticeSeverity = "info" | "warning";

/**
 * Service state of one electronic notification under Ley 39/2015 art. 43.2.
 *
 * Attributes: NO_ENTREGADA: AEAT has not put the notification at the
 * taxpayer's disposal yet, so no `fecha de notificación` exists and no window
 * has started. The placeholder state for a `pendiente` row. ACCEDIDA: The
 * taxpayer has accessed the contents. The notification is served by access,
 * which is the ordinary path and the one art. 43.2 names first. EN_PLAZO: Put
 * at the taxpayer's disposal and not yet accessed, with fewer than ten días
 * naturales elapsed. Still inside the window; not yet served. RECHAZO_TACITO:
 * Put at the taxpayer's disposal, never accessed, and ten or more días
 * naturales elapsed. Deemed rejected and therefore legally served — the state
 * that must reach the operator, because the taxpayer now bears a
 * notification's consequences without ever having read it.
 */
export type NotificacionEstadoServicio =
  "no_entregada" | "accedida" | "en_plazo" | "rechazo_tacito";

/**
 * Total partition of the registry modelo set by coverage disposition.
 *
 * Every `registry_modelo_codes` code lands in exactly one of the four tuples,
 * and construction refuses a report that places one code in two of them (or
 * twice in one). `advised` is the load-bearing field: a non-empty `advised`
 * means the default surface would otherwise have hidden a filing obligation
 * the operator must investigate.
 *
 * Attributes: surfaced: Modelos positively resolved by registry windows and
 * applicability for the queried schedule horizon. confidently_excluded:
 * Modelos the taxpayer model positively answers "no" for — answered, so no
 * advisory is raised. advised: Modelos the operator must investigate (window-
 * missing or applicability-undetermined), each with its
 * `CoverageAdviceReason`. out_of_scope: Modelos declared out of scope in
 * `OUT_OF_SCOPE_OBLIGATIONS`.
 */
export type ObligationCoverageReport = {
  surfaced: string[];
  confidently_excluded: string[];
  advised: AdvisedObligation[];
  out_of_scope: string[];
};

/**
 * Status of a single `ModeloDeadline` against a reference date.
 *
 * `UPCOMING` and `DUE_SOON` are differentiated by the engine's `due_soon_days`
 * window (default 14 days). `FILED` and `NOT_APPLICABLE` are reserved for
 * downstream consumers — the engine never produces them. `UNKNOWN` is produced
 * only for a projected window whose close is unknown, and is never derived
 * from a date.
 *
 * Attributes: UPCOMING: Window opens in the future or is open but more than
 * `due_soon_days` ahead of close. DUE_SOON: Window closes within
 * `due_soon_days` of the reference date. DUE_TODAY: Reference date is the
 * close date. OVERDUE: Reference date is past the close date. FILED:
 * Downstream marker for filings already submitted. NOT_APPLICABLE: Downstream
 * marker for obligations the profile no longer triggers. UNKNOWN: The window's
 * close is unknown because a holiday calendar its inhábil-day shift needs is
 * not published; the obligation is neither open-ended nor overdue, and is not
 * classified against its nominal close.
 */
export type ObligationStatus =
  | "UPCOMING"
  | "DUE_SOON"
  | "DUE_TODAY"
  | "OVERDUE"
  | "FILED"
  | "NOT_APPLICABLE"
  | "UNKNOWN";

